(function (window, document) {
    "use strict";

    if (window.Swiper) {
        return;
    }

    function toElement(target, scope) {
        if (!target) {
            return null;
        }
        if (typeof target === "string") {
            return (scope || document).querySelector(target);
        }
        return target;
    }

    function MiniSwiper(target, options) {
        this.el = toElement(target);
        this.options = options || {};
        this.wrapper = this.el ? this.el.querySelector(".swiper-wrapper") : null;
        this.slides = this.wrapper ? Array.prototype.slice.call(this.wrapper.children) : [];
        this.index = 0;
        this.timer = null;

        if (!this.el || !this.wrapper || this.slides.length === 0) {
            return;
        }

        this.setupPagination();
        this.setupNavigation();
        this.update();
        this.setupAutoplay();
    }

    MiniSwiper.prototype.setupPagination = function () {
        var pagination = this.options.pagination || {};
        this.paginationEl = toElement(pagination.el, this.el);
        this.bullets = [];

        if (!this.paginationEl) {
            return;
        }

        this.paginationEl.innerHTML = "";
        for (var i = 0; i < this.slides.length; i++) {
            var bullet = document.createElement("span");
            bullet.className = "swiper-pagination-bullet";
            bullet.setAttribute("role", "button");
            bullet.setAttribute("tabindex", "0");
            bullet.setAttribute("aria-label", "Go to slide " + (i + 1));
            this.paginationEl.appendChild(bullet);
            this.bullets.push(bullet);

            if (pagination.clickable) {
                this.bindBullet(bullet, i);
            }
        }
    };

    MiniSwiper.prototype.bindBullet = function (bullet, index) {
        var self = this;
        var activate = function () {
            self.goTo(index);
        };
        bullet.addEventListener("click", activate);
        bullet.addEventListener("keydown", function (event) {
            if (event.key === "Enter" || event.key === " ") {
                event.preventDefault();
                activate();
            }
        });
    };

    MiniSwiper.prototype.setupNavigation = function () {
        var navigation = this.options.navigation || {};
        var nextEl = toElement(navigation.nextEl, document);
        var prevEl = toElement(navigation.prevEl, document);
        var self = this;

        if (nextEl) {
            nextEl.addEventListener("click", function () {
                self.next();
            });
        }
        if (prevEl) {
            prevEl.addEventListener("click", function () {
                self.prev();
            });
        }
    };

    MiniSwiper.prototype.setupAutoplay = function () {
        var autoplay = this.options.autoplay;
        if (!autoplay || this.slides.length <= 1) {
            return;
        }

        var delay = parseInt(autoplay.delay, 10);
        if (!delay || delay < 500) {
            delay = 5000;
        }

        var self = this;
        this.timer = window.setInterval(function () {
            self.next();
        }, delay);

        if (autoplay.disableOnInteraction !== false) {
            this.el.addEventListener("mouseenter", function () {
                window.clearInterval(self.timer);
            });
            this.el.addEventListener("mouseleave", function () {
                window.clearInterval(self.timer);
                self.timer = window.setInterval(function () {
                    self.next();
                }, delay);
            });
        }
    };

    MiniSwiper.prototype.update = function () {
        this.wrapper.style.transform = "translate3d(" + (-100 * this.index) + "%, 0, 0)";
        for (var s = 0; s < this.slides.length; s++) {
            if (s === this.index) {
                this.slides[s].classList.add("swiper-slide-active");
            } else {
                this.slides[s].classList.remove("swiper-slide-active");
            }
        }
        for (var i = 0; i < this.bullets.length; i++) {
            if (i === this.index) {
                this.bullets[i].classList.add("swiper-pagination-bullet-active");
            } else {
                this.bullets[i].classList.remove("swiper-pagination-bullet-active");
            }
        }
    };

    MiniSwiper.prototype.goTo = function (index) {
        if (this.slides.length === 0) {
            return;
        }
        this.index = (index + this.slides.length) % this.slides.length;
        this.update();
    };

    MiniSwiper.prototype.next = function () {
        this.goTo(this.index + 1);
    };

    MiniSwiper.prototype.prev = function () {
        this.goTo(this.index - 1);
    };

    window.Swiper = MiniSwiper;
})(window, document);
